const dateTimeForInput = (value: string) => { const date = new Date(value); date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0, 16); };
const ageDays = (job: Job) => Math.floor((Date.now() - new Date(job.last_event_at || job.created_at).getTime()) / 86_400_000);
const ageTone = (job: Job) => ageDays(job) >= 35 ? 'red' : ageDays(job) >= 16 ? 'yellow' : 'normal';
const ageBadge = (job: Job) => { const days = ageDays(job); if (days < 16) return ''; const tone = ageTone(job); return `<span class="rounded px-2 py-1 text-xs font-medium ${tone === 'red' ? 'bg-red-100 text-red-800' : 'bg-yellow-100 text-yellow-800'}">${days} дн. без события</span>`; };
