async function api(url: string, init?: RequestInit) { const headers = new Headers(init?.headers); if (init?.body !== undefined && !headers.has('content-type')) headers.set('content-type', 'application/json'); const response = await fetch(url, { ...init, headers }); if (!response.ok && response.status !== 204) { const payload = await response.json().catch(() => ({ error: response.statusText })) as { error?: string; details?: { fieldErrors?: Record<string, string[]>; formErrors?: string[] } }; const details = [...Object.values(payload.details?.fieldErrors ?? {}).flat(), ...(payload.details?.formErrors ?? [])]; throw new Error(details.length ? `${payload.error ?? response.statusText}: ${details.join(', ')}` : payload.error ?? response.statusText); } return response.status === 204 ? undefined : response.json(); }
