async function syncFromToolbar(button: HTMLButtonElement) { if (toolbarSyncRunning) return; toolbarSyncRunning = true; button.disabled = true; button.classList.add('cursor-wait', 'opacity-70'); const original = button.innerHTML; button.innerHTML = '<svg aria-hidden="true" class="h-5 w-5 animate-spin fill-none stroke-current" viewBox="0 0 24 24" stroke-width="2"><path d="M20 11a8 8 0 0 0-14-4l-2 2M4 13a8 8 0 0 0 14 4l2-2"/><path d="M4 5v4h4M20 19v-4h-4"/></svg>'; try { const state = await api('/api/email/sync/status') as ImapSettings; if (state.last_sync_status === 'running') { show('Синхронизация почты уже выполняется.'); return; } const result = await api('/api/settings/imap/sync', { method: 'POST' }) as { processed: number; reviewItems: number }; await loadJobs(); show(`Синхронизация: ${result.processed} писем, на проверке ${result.reviewItems}.`); } catch (error) { show((error as Error).message, true); } finally { toolbarSyncRunning = false; button.disabled = false; button.classList.remove('cursor-wait', 'opacity-70'); button.innerHTML = original; } }
