function matchIndicator(job: Job) { const match = job.ai_match; if (!match) return `<button data-match-modal="${job.id}" aria-label="AI: анализ не выполнялся" class="group relative block rounded-full p-1"><span class="block h-2.5 w-2.5 rounded-full bg-gray-400"></span><span role="tooltip" class="pointer-events-none absolute right-0 top-6 z-20 w-56 rounded-lg bg-gray-900 p-3 text-left text-xs font-normal text-white opacity-0 shadow-lg transition-opacity group-hover:opacity-100 group-focus:opacity-100">AI-анализ ещё не выполнялся. Нажмите, чтобы открыть.</span></button>`; const labels: Record<MatchClassification, [string, string]> = { strong: ['Сильное соответствие', 'bg-emerald-500'], potential: ['Частичное соответствие', 'bg-amber-500'], weak: ['Существенные несоответствия', 'bg-red-500'], insufficient_data: ['Недостаточно данных', 'bg-gray-400'] }; const [label, color] = match.outdated ? ['Результат устарел', 'bg-slate-500'] : labels[match.classification]; const summary = match.result.fit_summary || match.result.summary || match.result.vacancy_summary || 'Откройте анализ для подробностей.'; return `<button data-match-modal="${job.id}" aria-label="AI: ${label}" class="group relative block rounded-full p-1"><span class="block h-2.5 w-2.5 rounded-full ${color}"></span><span role="tooltip" class="pointer-events-none absolute right-0 top-6 z-20 w-64 rounded-lg bg-gray-900 p-3 text-left text-xs font-normal text-white opacity-0 shadow-lg transition-opacity group-hover:opacity-100 group-focus:opacity-100"><strong class="block text-sm">${label}</strong><span class="mt-1 block text-gray-200">${escape(summary)}</span><span class="mt-1 block text-gray-400">${formatDateTime(match.completed_at)} · ${escape(match.model)}</span></span></button>`; }
function interviewIndicator(job: Job) { const appointment = job.next_interview; if (job.status !== 'interview' || !appointment) return ''; const label = `${appointment.status === 'proposed' ? 'Предложенное ' : ''}интервью: ${formatDateTime(appointment.starts_at)} · ${appointmentFormatLabels[appointment.format]}`; const icon = '<svg aria-hidden="true" viewBox="0 0 24 24" class="h-4 w-4 fill-none stroke-current" stroke-width="2"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M8 14h3M8 17h5"/></svg>'; const trigger = appointment.meeting_url ? `<a data-interview-link href="${escape(appointment.meeting_url)}" target="_blank" rel="noopener noreferrer" aria-label="${escape(label)}. Открыть ссылку встречи" class="rounded p-1 text-violet-700 hover:bg-violet-100">${icon}</a>` : `<button data-open="${job.id}" aria-label="${escape(label)}" class="rounded p-1 text-violet-700 hover:bg-violet-100">${icon}</button>`; return `<span class="group relative inline-flex">${trigger}<span role="tooltip" class="pointer-events-none absolute left-0 top-7 z-30 w-56 rounded-lg bg-gray-900 p-3 text-left text-xs font-normal text-white opacity-0 shadow-lg transition-opacity group-hover:opacity-100 group-focus-within:opacity-100"><strong class="block text-sm">${appointment.status === 'proposed' ? 'Нужно подтвердить' : 'Ближайшее интервью'}</strong><span class="mt-1 block text-gray-200">${formatDateTime(appointment.starts_at)} · ${appointmentStageLabels[appointment.stage]} · ${appointmentFormatLabels[appointment.format]}</span>${appointment.note ? `<span class="mt-1 block text-gray-400">${escape(appointment.note)}</span>` : ''}${appointment.meeting_url ? '<span class="mt-2 block text-violet-200">Нажмите на календарь, чтобы открыть встречу.</span>' : ''}</span></span>`; }
function renderDetailMatchTrigger(job: Job) { const button = $('#detail-match-trigger'); const match = job.ai_match; const state = !match ? ['AI Match: анализ не выполнялся', 'border-gray-300 bg-white text-gray-600 hover:bg-gray-50 hover:text-gray-800'] : match.outdated ? ['AI Match: результат устарел', 'border-amber-300 bg-amber-50 text-amber-800 hover:bg-amber-100'] : ({ strong: ['AI Match: сильное соответствие', 'border-emerald-300 bg-emerald-50 text-emerald-800 hover:bg-emerald-100'], potential: ['AI Match: частичное соответствие', 'border-amber-300 bg-amber-50 text-amber-800 hover:bg-amber-100'], weak: ['AI Match: существенные несоответствия', 'border-red-300 bg-red-50 text-red-800 hover:bg-red-100'], insufficient_data: ['AI Match: недостаточно данных', 'border-blue-300 bg-blue-50 text-blue-800 hover:bg-blue-100'] } satisfies Record<MatchClassification, [string, string]>)[match.classification]; button.className = `rounded-lg border p-2.5 ${state[1]}`; button.title = state[0]; button.setAttribute('aria-label', state[0]); }
