function card(job: Job) { const waitingTone = ageTone(job); const colors = waitingTone === 'red' ? 'border-red-300 bg-red-50' : waitingTone === 'yellow' ? 'border-yellow-300 bg-yellow-50' : 'border-gray-200 bg-white'; const controls = `<div class="absolute right-1.5 top-1.5 flex items-center gap-0.5">${interviewIndicator(job)}${matchIndicator(job)}${archiveCardButton(job.id)}</div>`; const metadata = `<p class="truncate text-xs text-gray-500">${escape(job.location)}</p>`; const title = (compact: boolean) => `<div class="flex min-w-0 items-start gap-1.5">${freshnessMarker(job)}<p class="min-w-0 ${compact ? 'text-sm leading-snug' : 'text-sm'} font-semibold text-gray-900">${escape(job.title)}</p></div>`; if (viewState.compactCards) return `<article draggable="true" data-drag-job="${job.id}" class="relative cursor-grab rounded-lg border p-2 shadow-sm active:cursor-grabbing ${colors}">${controls}<button data-open="${job.id}" class="block w-full pr-14 text-left">${title(true)}<p class="mt-1 truncate text-xs text-gray-600">${escape(job.company)}</p><div class="mt-1 flex items-center justify-between gap-2"><div class="min-w-0">${metadata}</div>${ageBadge(job)}</div></button></article>`; return `<article draggable="true" data-drag-job="${job.id}" class="relative cursor-grab rounded-lg border p-3 shadow-sm active:cursor-grabbing ${colors}">${controls}<button data-open="${job.id}" class="block w-full pr-14 text-left">${title(false)}<p class="mt-1 text-sm text-gray-600">${escape(job.company)}</p><div class="mt-1">${metadata}</div>${tagPills(job.tags)}</button><div class="mt-3 flex items-center justify-between gap-2">${ageBadge(job)}</div></article>`; }
function boardColumns(groupJobs: Job[]) { const columnTemplate = stages.map(stage => viewState.collapsedStages.includes(stage.status) ? '3rem' : 'minmax(0,1fr)').join(' '); return `<div class="kanban-columns grid w-full grid-cols-1 items-start gap-4 md:grid-cols-2 lg:grid-cols-4" style="--board-columns:${columnTemplate}">${stages.map(stage => { const stageJobs = groupJobs.filter(job => job.status === stage.status); const colors = stageColors[stage.status]; const collapsed = viewState.collapsedStages.includes(stage.status); const header = collapsed ? `<button type="button" data-toggle-column="${stage.status}" title="Развернуть этап ${stage.label}" aria-label="Развернуть этап ${stage.label}" class="kanban-column-vertical-label ${colors.heading}"><span>${stage.label}</span><span class="rounded px-1.5 py-0.5 text-xs font-medium ${colors.count}">${stageJobs.length}</span></button>` : `<div class="mb-1 flex items-center justify-between gap-2"><h2 class="font-semibold ${colors.heading}">${stage.label}</h2><div class="flex items-center gap-1"><span class="rounded px-2 py-1 text-xs font-medium ${colors.count}">${stageJobs.length}</span><button type="button" data-toggle-column="${stage.status}" title="Свернуть этап ${stage.label}" aria-label="Свернуть этап ${stage.label}" class="rounded p-1 text-gray-500 hover:bg-white/70 hover:text-gray-800"><svg aria-hidden="true" viewBox="0 0 24 24" class="h-4 w-4 fill-none stroke-current" stroke-width="2"><path d="m14 6-6 6 6 6"/></svg></button></div></div>`; return `<section data-drop-status="${stage.status}" class="kanban-column rounded-lg border p-3 transition-shadow ${collapsed ? 'kanban-column--collapsed' : ''} ${colors.column}">${header}<div class="kanban-column-content"><p class="mb-3 text-xs text-gray-500">Перетащите карточку сюда</p><div class="${viewState.compactCards ? 'space-y-2' : 'space-y-3'}">${stageJobs.map(card).join('') || `<p class="rounded border border-dashed p-4 text-center text-sm ${colors.empty}">Пока пусто</p>`}</div></div></section>`; }).join('')}</div>`; }
function boardGroups() { if (!viewState.group) return [{ label: '', jobs }]; const buckets = new Map<string, Job[]>(); const add = (label: string, job: Job) => buckets.set(label, [...(buckets.get(label) ?? []), job]); for (const job of jobs) { if (viewState.group === 'tag') { if (job.tags.length) job.tags.forEach(tag => add(tag.name, job)); else add('Без тегов', job); } else if (viewState.group === 'company') add(job.company || 'Без компании', job); else if (viewState.group === 'location') add(job.location || 'Без локации', job); else if (viewState.group === 'source') add(job.source || 'Другой источник', job); else add(new Intl.DateTimeFormat('ru-RU', { month: 'long', year: 'numeric' }).format(new Date(job.created_at)), job); } return [...buckets.entries()].sort(([left], [right]) => left.localeCompare(right, 'ru')).map(([label, groupJobs]) => ({ label, jobs: groupJobs })); }
