function archiveEmailLogColumn() { const tabs: Array<[EmailLogFilter, string, number, string]> = [['attention', 'Внимание', emailLogCounts.unlinked + emailLogCounts.uncertain, 'border-amber-400 bg-amber-400/15 text-amber-100'], ['unlinked', 'Нет связи', emailLogCounts.unlinked, 'border-red-400 bg-red-400/15 text-red-100'], ['uncertain', 'Не точно', emailLogCounts.uncertain, 'border-amber-400 bg-amber-400/15 text-amber-100'], ['exact', 'Точно', emailLogCounts.exact, 'border-emerald-400 bg-emerald-400/15 text-emerald-100'], ['all', 'Все', emailLogTotal, 'border-slate-500 bg-slate-700 text-slate-100']]; const visible = emailLog.filter(item => emailLogFilter === 'all' || (emailLogFilter === 'attention' ? emailLogKind(item) !== 'exact' : emailLogKind(item) === emailLogFilter)); const tone = (item: EmailLogEntry) => emailLogKind(item) === 'unlinked' ? ['border-red-400/60 bg-red-400/10', 'bg-red-400', 'Нет связи'] : emailLogKind(item) === 'uncertain' ? ['border-amber-400/60 bg-amber-400/10', 'bg-amber-400', 'Нужна проверка'] : ['border-emerald-400/60 bg-emerald-400/10', 'bg-emerald-400', 'Точное совпадение']; return `<section class="rounded-lg border border-slate-700 bg-slate-900 p-3 text-slate-100"><div class="mb-3 flex items-start justify-between gap-2"><div><h2 class="font-semibold">Журнал писем</h2><p class="mt-0.5 text-xs text-slate-400">Техническая очередь · без вложений</p></div><span class="rounded bg-slate-700 px-2 py-1 text-xs font-medium text-slate-100">${visible.length}/${emailLogTotal}</span></div><div class="mb-3 flex flex-wrap gap-1">${tabs.map(([filter, label, count, active]) => `<button data-email-log-filter="${filter}" class="rounded border px-1.5 py-1 text-[11px] font-medium ${emailLogFilter === filter ? active : 'border-slate-700 text-slate-400 hover:bg-slate-800'}">${label} <span class="ml-0.5 opacity-80">${count}</span></button>`).join('')}</div><div data-email-log-list class="max-h-[34rem] space-y-1.5 overflow-y-auto overscroll-contain pr-1 sm:max-h-[calc(100vh-18rem)]">${visible.map(item => { const [border, dot, label] = tone(item); return `<details data-email-log="${item.id}" class="rounded border ${border} p-2"><summary class="flex cursor-pointer items-center gap-2 text-xs"><span class="h-2 w-2 shrink-0 rounded-full ${dot}"></span><span class="min-w-0 flex-1 truncate font-medium text-slate-100">${escape(item.job_company ?? 'Вакансия не найдена')}${item.job_title ? ` · ${escape(item.job_title)}` : ''}</span><span class="shrink-0 text-[10px] text-slate-400">${formatDate(item.received_at)}</span></summary><div class="mt-2 border-t border-slate-700/80 pt-2"><p class="text-xs font-medium text-slate-200">${label} · ${escape(reviewLabel(item))}</p>${item.unresolved_reason ? `<p class="mt-1 text-xs text-slate-400">${escape(item.unresolved_reason)}</p>` : ''}<div data-email-log-body="${item.id}" class="mt-2 text-xs text-slate-400">Откройте запись, чтобы загрузить текст письма.</div></div></details>`; }).join('') || '<p class="rounded border border-dashed border-slate-700 p-4 text-center text-sm text-slate-400">В этой группе писем нет.</p>'}</div>${emailLogTotal > emailLog.length ? '<button id="email-log-more" class="mt-3 w-full rounded border border-slate-600 px-2 py-1.5 text-xs font-medium text-slate-200 hover:bg-slate-800">Загрузить ещё 50 записей</button>' : ''}</section>`; }
async function loadMoreEmailLog() { const page = await api(`/api/email/log?limit=50&offset=${emailLogLoaded}`) as EmailLogPage; emailLog = [...emailLog, ...page.items.filter(item => !emailLog.some(existing => existing.id === item.id))]; emailLogLoaded += page.items.length; emailLogTotal = page.total; emailLogCounts = page.counts; renderArchiveBoard(); }
