  const syncButton = $('#imap-sync') as HTMLButtonElement; if (syncing) { syncButton.disabled = true; syncButton.classList.add('cursor-wait', 'opacity-70'); syncButton.innerHTML = '<svg aria-hidden="true" class="mr-1 inline h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none"><circle class="opacity-25" cx="12" cy="12" r="9" stroke="currentColor" stroke-width="3"/><path class="opacity-75" fill="currentColor" d="M12 3a9 9 0 0 1 9 9h-3a6 6 0 0 0-6-6V3z"/></svg>Синхронизация…'; window.setTimeout(() => void loadImapPanel().catch(error => show(error.message, true)), 1_500); } else syncButton.onclick = () => { syncButton.disabled = true; syncButton.classList.add('cursor-wait', 'opacity-70'); syncButton.innerHTML = '<svg aria-hidden="true" class="mr-1 inline h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none"><circle class="opacity-25" cx="12" cy="12" r="9" stroke="currentColor" stroke-width="3"/><path class="opacity-75" fill="currentColor" d="M12 3a9 9 0 0 1 9 9h-3a6 6 0 0 0-6-6V3z"/></svg>Синхронизация…'; void api('/api/settings/imap/sync', { method: 'POST' }).then((result: { processed: number; reviewItems: number }) => loadImapPanel().then(() => show(`Синхронизация: ${result.processed} писем, на проверке ${result.reviewItems}.`))).catch(error => { syncButton.disabled = false; syncButton.classList.remove('cursor-wait', 'opacity-70'); syncButton.textContent = 'Синхронизировать'; show(error.message, true); }); };
