    const fields: Array<[keyof GenericParseFields, string, string]> = [['title', '#detail-title-input', 'позицию'], ['company', '#detail-company-input', 'компанию'], ['location', '#detail-location-input', 'локацию'], ['workplace_type', '#detail-workplace-input', 'формат работы'], ['employment_type', '#detail-employment-input', 'занятость']];
    const applied: string[] = []; for (const [key, selector, label] of fields) { const value = result.fields[key]; if (value) { ($(selector) as HTMLInputElement).value = value; applied.push(label); } }
    status.classList.remove('text-red-700'); status.textContent = applied.length ? `AI заполнил: ${applied.join(', ')}. Проверьте поля и нажмите «Сохранить».` : 'AI не смог уверенно определить поля. Проверьте карточку вручную.';
